/* MUTANT: one refusal broken on purpose. The gate MUST go red against this
 * file. Generated by mut/make.py; never edited by hand.
 */
/* <ov-vitals> - the numerics beside a bed, each saying where it came from and how old it is.
 *
 * Heart rate, SpO2,
 * blood pressure, breathing rate and temperature, one narrow row each, as the
 * numeric column of a bedside monitor: the name and source, a trend, the
 * number. The ECG strip is <ov-ecg>, and the silhouette beside the name is
 * <ov-avatar>, whose status mark this element supplies (`avatar`).
 *
 *   <ov-vitals label="BED 4" avatar="bed4-who" trend-window="1800"></ov-vitals>
 *   v.vitals = {
 *     hr:   { value: 72, source: 'ecg', lead: 'II', limits: [50, 120] },
 *     spo2: { value: 97, perf: 1.4, limits: [90, 100] },
 *     nibp: { sys: 118, dia: 76, mean: 90, ago: 240, mode: 'auto', interval: 900 },
 *     rr:   { value: 16, source: 'impedance' },
 *     temp: { value: 36.8, unit: 'C', site: 'core' },
 *   };
 *
 * `ago` is seconds before the reading was handed in. Absent on a continuous
 * parameter, it means the value is current as of the hand-over, and the
 * element ages it from there. Absent on a blood pressure, it means NOBODY
 * SAID WHEN, and that is written out.
 *
 * The trend is what was handed in, recorded by the element at each hand-over,
 * plus any history a hand-over carries as `trend: [[ago, value], ...]` (for a
 * blood pressure, `[[ago, sys, dia, mean?], ...]`). Nothing is interpolated.
 *
 * Quotes are from the Philips IntelliVue MX400-800 Instructions for Use,
 * read in full text.
 *
 * ── THE REFUSAL ───────────────────────────────────────────────────────────
 *
 * 🔴 A BLOOD PRESSURE IS A MEASUREMENT THAT WAS TAKEN, NOT ONE BEING TAKEN.
 * NIBP is intermittent: a cuff inflates, a number results, and the number
 * stays on the screen long after the pressure it measured has changed. So it
 * is NEVER drawn in the form of a live numeric, always carries its age, greys
 * as it ages, and is withdrawn once invalid. STATED, IFU p. 206: "The measured
 * NBP value ... will be displayed for one hour. After that the values are
 * regarded as invalid and are no longer displayed. During this hour,
 * measurement values may be grayed out ... This avoids older numerics being
 * misinterpreted as current data." The ten-minute default for greying is
 * from the defaults table, whose extraction is garbled: LIKELY, not confirmed.
 * A blood pressure with no time given is shown aged and says so.
 * While the cuff inflates, the cuff pressure is shown AS a cuff pressure:
 * "The cuff pressure is displayed instead of the units" (p. 207).
 * In the trend, each blood pressure is its own bar from diastolic to systolic
 * at the time it was taken, and bars are NEVER joined: a line between two
 * cuff readings would draw a pressure nobody measured.
 *
 * And, each in the monitor's own terms:
 *
 * 1. SpO2 THAT CANNOT BE READ IS -?-, NEVER THE LAST GOOD NUMBER. Sensor off,
 *    no sensor and a noisy signal replace the numeric; low perfusion and a
 *    poor signal leave it with a ? beside it. STATED, p. 81: "the measurement
 *    numeric will be replaced by -?-. If an INOP may lead to unreliable
 *    measurement values, a ? appears next to the numeric." NoisySignal is
 *    "Excessive patient movement" (p. 90). Perfusion under 0.3 is "marginal"
 *    (p. 200) and takes the ?. Which INOP takes which form is read from the
 *    INOP table, whose columns extract badly: PARTLY STATED.
 * 2. A HEART RATE NAMES ITS SOURCE. HR is from the ECG; PULSE is from the
 *    pleth, an arterial line or the cuff. STATED, p. 181: "The displayed pulse
 *    numeric is labeled and colorcoded to match its source wave." A rate with
 *    no source is shown with a ? and claims no alarm. A pulse from the pleth
 *    is -?- while its own SpO2 sensor is off (INFERRED: it is the same wave).
 *    A pulse standing in for a lost ECG says the ECG and arrhythmia alarms are
 *    off, STATED p. 182-183. A pulse from the cuff is intermittent, ages like
 *    the blood pressure, and never alarms: "There are no alarms associated
 *    with pulse from NBP" (p. 209). The trend breaks where the source changes.
 * 3. A NUMBER THAT STOPPED ARRIVING IS NOT A NUMBER. A continuous parameter
 *    older than `stale` seconds (default 15; temperature 60) is -?- with NO
 *    UPDATE, and its trend line BREAKS across the silence and ends at the last
 *    sample, short of now. INFERRED from the -?- rule; the IFU names no such
 *    timeout.
 * 4. HR = RR IS SAID. When the breathing rate matches the heart rate the
 *    impedance counter may be counting the heart: "HR = RR" (p. 186), and
 *    "Cardiac overlay can ... lead to a false indication of a high
 *    respiration rate or an undetected apnea condition" (p. 187). Shown with
 *    a ?.
 * 5. A TEMPERATURE NAMES ITS SITE AND UNIT, or takes a ?. STATED only as
 *    labelling, p. 211: "The label is a unique identifier for each type of
 *    temperature." That a site-less value is questionable is INFERRED.
 * 6. AN ALARM NEEDS BOTH LIMITS, AND ALARMS OFF IS SHOWN BESIDE THE NUMBER.
 *    STATED, p. 65: "The alarms off symbol is shown beside the measurement
 *    numeric." The limits are drawn as a band on the trend only when both are
 *    set. A parameter listed and not handed in is NOT MEASURED, never left out.
 *
 * Status for the avatar: bad on any alarm or any -?-; note on any ?, an aged
 * or invalid blood pressure, a cuff inflating or alarms off; unknown with
 * nothing handed in; ok otherwise. It is written to the avatar, which decides
 * nothing itself.
 *
 * No animation frames. One timer, at the next moment something changes
 * form (a value going stale, a blood pressure's age crossing a minute), and
 * only after the page has arrived.
 */

import { define, whenArrived } from '../../../src/ov-core.js';

const ALL = ['hr', 'spo2', 'nibp', 'rr', 'temp'];
const UNIT = { hr: 'bpm', spo2: '%', nibp: 'mmHg', rr: 'rpm', temp: '' };
const NBP_INVALID_S = 3600;
const HISTORY = 2000;
const SPO2_INTERRUPT = { 'sensor-off': 'SENSOR OFF', 'no-sensor': 'NO SENSOR', noisy: 'NOISY SIGNAL' };
const SPO2_QUESTION = { 'low-perf': 'LOW PERFUSION', 'poor-signal': 'POOR SIGNAL' };
const MODES = { manual: 'MANUAL', auto: 'AUTO', sequence: 'SEQUENCE', stat: 'STAT' };

const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const val = (x) => (x === null || x === undefined || x === '' ? NaN : Number(x));
const fin = (x) => Number.isFinite(val(x));
const trim = (x) => String(Number(val(x).toFixed(1)));
const f1 = (x) => x.toFixed(1);

export function ageWords(s) {
  const n = Math.max(0, Math.floor(s));
  if (n < 60) return 'UNDER 1 MIN';
  if (n < 3600) return `${Math.floor(n / 60)} MIN`;
  return `${Math.floor(n / 3600)} H ${String(Math.floor(n / 60) % 60).padStart(2, '0')} MIN`;
}

export class OvVitals extends HTMLElement {
  static observedAttributes = ['params', 'stale', 'nibp-aged', 'trend-window', 'src', 'source', 'avatar', 'label', 'demo'];

  /* Our clock, in epoch ms. Replaceable so a test can drive time. */
  static now = () => Date.now();

  constructor() {
    super();
    this._hist = {};
  }

  connectedCallback() {
    this.fetchSrc();
    this.bindSource();
    this.paint();
  }

  disconnectedCallback() {
    this.unschedule();
    if (this.unsub) this.unsub();
    this.unsub = null;
  }

  attributeChangedCallback(name) {
    if (!this.isConnected) return;
    if (name === 'src') { this.fetchSrc(); return; }
    if (name === 'source') this.bindSource();
    this.paint();
  }

  async fetchSrc() {
    const src = this.getAttribute('src');
    if (!src) return;
    let data = null;
    try {
      const r = await fetch(src);
      if (!r.ok) throw new Error(String(r.status));
      data = await r.json();
    } catch { data = null; }
    if (this.getAttribute('src') === src) this.vitals = data;
  }

  bindSource() {
    if (this.unsub) this.unsub();
    this.unsub = null;
    const name = this.getAttribute('source');
    if (name && window.Overscan?.subscribe) this.unsub = window.Overscan.subscribe(name, (x) => { this.vitals = x; });
  }

  get vitals() { return this._v || null; }
  set vitals(v) {
    this._v = v && typeof v === 'object' ? v : null;
    this._at = OvVitals.now();
    if (this._v) this.record(this._v);
    this.paint();
  }

  /* Forget every recorded trend, as when a monitor is moved to a new patient. */
  clearTrends() { this._hist = {}; this.paint(); }

  params() {
    const p = (this.getAttribute('params') || '').split(',').map((x) => x.trim()).filter((x) => ALL.includes(x));
    return p.length ? p : ALL;
  }

  /* A positive number from an attribute's raw value, or the default. Called
   * with each attribute read by its literal name, so the manifest sees it. */
  attrNum(raw, dflt) { const v = val(raw); return Number.isFinite(v) && v > 0 ? v : dflt; }

  /* ---- the record: what was handed in, and when ---------------------------- */

  record(V) {
    for (const key of ALL) {
      const p = V[key] && typeof V[key] === 'object' ? V[key] : null;
      if (!p) continue;
      const list = (this._hist[key] ||= []);
      const src = String(p.source ?? '').toLowerCase();
      const add = (e) => { if (!list.some((x) => Math.abs(x.t - e.t) < (key === 'nibp' ? 5000 : 1))) list.push(e); };
      if (Array.isArray(p.trend)) {
        for (const row of p.trend) {
          if (!Array.isArray(row) || !fin(row[0])) continue;
          const t = this._at - val(row[0]) * 1000;
          if (key === 'nibp') { if (fin(row[1]) && fin(row[2])) add({ t, sys: val(row[1]), dia: val(row[2]), mean: fin(row[3]) ? val(row[3]) : null }); }
          else add({ t, v: fin(row[1]) ? val(row[1]) : null, s: src });
        }
      }
      if (key === 'nibp') {
        if (!p.measuring && fin(p.sys) && fin(p.dia) && fin(p.ago)) {
          add({ t: this._at - val(p.ago) * 1000, sys: val(p.sys), dia: val(p.dia), mean: fin(p.mean) ? val(p.mean) : null });
        }
      } else {
        const t = fin(p.ago) && val(p.ago) >= 0 ? this._at - val(p.ago) * 1000 : this._at;
        const spo2 = V.spo2 && typeof V.spo2 === 'object' ? V.spo2 : null;
        // A value the display withholds is recorded as a gap, never as a value.
        const blocked = key === 'spo2' ? Object.hasOwn(SPO2_INTERRUPT, String(p.inop ?? '').toLowerCase()) || (p.inop && !Object.hasOwn(SPO2_QUESTION, String(p.inop).toLowerCase()))
          : !!p.inop || (key === 'hr' && (src === 'pleth' || src === 'spo2') && spo2 && Object.hasOwn(SPO2_INTERRUPT, spo2.inop));
        add({ t, v: !blocked && fin(p.value) ? val(p.value) : null, s: src });
      }
      list.sort((a, b) => a.t - b.t);
      if (list.length > HISTORY) list.splice(0, list.length - HISTORY);
    }
  }

  /* ---- what each number may claim ----------------------------------------- */

  judge(key, V, now) {
    const p = V && V[key] && typeof V[key] === 'object' ? V[key] : null;
    const t = { key, label: key === 'spo2' ? 'SpO₂' : key === 'nibp' ? 'NBP' : key.toUpperCase(), src: '', text: '-?-', unit: UNIT[key],
      mark: 'withheld', words: '', limits: null, alarm: false, alarmsOff: false, age: null, next: null, staleMs: Infinity };
    if (!p) { t.mark = 'absent'; t.text = ''; t.words = 'NOT MEASURED'; return t; }

    const L = Array.isArray(p.limits) ? p.limits : [];
    if (fin(L[0]) && fin(L[1])) t.limits = [val(L[0]), val(L[1])];
    t.alarmsOff = p.alarms === false;
    const intermittent = key === 'nibp' || (key === 'hr' && String(p.source).toLowerCase() === 'nbp');
    const at = fin(p.ago) && val(p.ago) >= 0 ? this._at - val(p.ago) * 1000 : intermittent ? null : this._at;
    t.age = at === null ? null : (now - at) / 1000;
    const staleS = fin(p.maxAge) && val(p.maxAge) > 0 ? val(p.maxAge) : key === 'temp' ? Math.max(60, this.attrNum(this.getAttribute('stale'), 15)) : this.attrNum(this.getAttribute('stale'), 15);
    if (!intermittent) t.staleMs = staleS * 1000;
    const stale = () => {
      if (intermittent || t.age === null) return false;
      if (false /* MUTANT: never stale */) { t.mark = 'withheld'; t.text = '-?-'; t.words = `NO UPDATE FOR OVER ${staleS} S`; return true; }
      t.next = at + staleS * 1000 + 1;
      return false;
    };

    this[key](p, t, V, stale, intermittent, at);

    // Refusal 6: an alarm needs both limits, a shown number, and alarms on.
    const compared = t.mark === 'live' || (key === 'nibp' && (t.mark === 'taken' || t.mark === 'aged'));
    const x = key === 'nibp' ? val(p.sys) : val(p.value);
    if (compared && t.limits && !t.alarmsOff && !(key === 'hr' && intermittent)) t.alarm = x < t.limits[0] || x > t.limits[1];
    return t;
  }

  hr(p, t, V, stale, intermittent) {
    const src = String(p.source ?? '').toLowerCase();
    if (src === 'ecg') { t.label = 'HR'; t.src = `ECG${p.lead ? ` ${String(p.lead).toUpperCase()}` : ', LEAD NOT NAMED'}`; }
    else if (src === 'pleth' || src === 'spo2') { t.label = 'PULSE'; t.src = 'SpO₂ PLETH'; }
    else if (src === 'art' || src === 'abp') { t.label = 'PULSE'; t.src = 'ART LINE'; }
    else if (src === 'nbp') { t.label = 'PULSE'; t.src = 'NBP CUFF'; }
    else { t.label = 'RATE'; t.src = 'SOURCE NOT STATED'; }
    const spo2 = V.spo2 && typeof V.spo2 === 'object' ? V.spo2 : null;
    if (!fin(p.value) || val(p.value) < 0) { t.words = 'NO RATE REPORTED'; return; }
    if (src === 'ecg' && p.inop) { t.words = String(p.inop).toUpperCase().replace(/-/g, ' '); return; }
    if ((src === 'pleth' || src === 'spo2') && spo2 && Object.hasOwn(SPO2_INTERRUPT, spo2.inop)) {
      t.words = `ITS SOURCE, SpO₂, IS ${SPO2_INTERRUPT[spo2.inop]}`;
      return;
    }
    t.text = String(Math.round(val(p.value)));
    if (intermittent) { this.aging(t, 'NO ALARMS FROM A CUFF PULSE'); return; }
    if (stale()) return;
    if (!t.src || t.label === 'RATE') { t.mark = 'questionable'; t.words = 'SOURCE NOT STATED · NO ALARM CLAIM'; t.limits = null; return; }
    t.mark = 'live';
    if (p.fallback && src !== 'ecg') t.words = 'ECG UNAVAILABLE · ECG AND ARRHYTHMIA ALARMS OFF';
  }

  spo2(p, t, V, stale) {
    const inop = p.inop ? String(p.inop).toLowerCase() : '';
    if (fin(p.perf)) t.src = `PERF ${trim(p.perf)}`;
    if (Object.hasOwn(SPO2_INTERRUPT, inop)) { t.words = SPO2_INTERRUPT[inop]; return; }
    if (inop && !Object.hasOwn(SPO2_QUESTION, inop)) { t.words = `INOP ${inop.toUpperCase()}`; return; }
    if (!fin(p.value)) { t.words = 'NO VALUE REPORTED'; return; }
    t.text = String(Math.round(val(p.value)));
    if (stale()) return;
    if (inop) { t.mark = 'questionable'; t.words = SPO2_QUESTION[inop]; return; }
    if (fin(p.perf) && val(p.perf) < 0.3) { t.mark = 'questionable'; t.words = 'PERFUSION MARGINAL, UNDER 0.3'; return; }
    t.mark = 'live';
  }

  nibp(p, t) {
    const mode = MODES[String(p.mode ?? '').toLowerCase()];
    t.src = mode ? `${mode}${mode === 'AUTO' && fin(p.interval) ? ` ${ageWords(val(p.interval))}` : ''}` : '';
    if (p.measuring && fin(p.measuring.cuff)) {
      t.mark = 'measuring';
      t.text = String(Math.round(val(p.measuring.cuff)));
      t.unit = 'mmHg CUFF';
      t.words = 'MEASURING · NOT A BLOOD PRESSURE YET';
      return;
    }
    if (!fin(p.sys) || !fin(p.dia)) { t.words = 'NO MEASUREMENT'; return; }
    t.text = `${Math.round(val(p.sys))}/${Math.round(val(p.dia))}${fin(p.mean) ? ` (${Math.round(val(p.mean))})` : ''}`;
    this.aging(t, '');
  }

  /* The intermittent form: taken, aged, invalid. Never live. */
  aging(t, tail) {
    const agedS = this.attrNum(this.getAttribute('nibp-aged'), 600);
    const plus = tail ? ` · ${tail}` : '';
    if (t.age === null) { t.mark = 'aged'; t.words = `TIME OF MEASUREMENT NOT GIVEN${plus}`; return; }
    const at = OvVitals.now() - t.age * 1000;
    if (t.age >= NBP_INVALID_S) {
      t.mark = 'invalid';
      t.text = '';
      t.words = `NO VALID ${t.key === 'nibp' ? 'NBP' : 'CUFF PULSE'} · LAST TAKEN ${ageWords(t.age)} AGO, INVALID AFTER 1 H`;
      t.next = at + (Math.floor(t.age / 60) + 1) * 60000;
      return;
    }
    t.mark = t.age >= agedS ? 'aged' : 'taken';
    t.words = `TAKEN ${ageWords(t.age)} AGO${t.mark === 'aged' ? ' · AGED' : ''}${plus}`;
    // The next minute of age, which also carries it across aged and invalid.
    t.next = at + Math.min((Math.floor(t.age / 60) + 1) * 60, t.age < agedS ? agedS : NBP_INVALID_S) * 1000;
  }

  rr(p, t, V, stale) {
    const src = String(p.source ?? '').toLowerCase();
    t.src = src === 'impedance' ? 'IMPEDANCE' : src === 'co2' || src === 'etco2' ? 'CO₂' : 'SOURCE NOT STATED';
    if (p.inop) { t.words = String(p.inop).toUpperCase().replace(/-/g, ' '); return; }
    if (!fin(p.value)) { t.words = 'NO RATE REPORTED'; return; }
    t.text = String(Math.round(val(p.value)));
    if (stale()) return;
    if (p.hrEqualsRr) { t.mark = 'questionable'; t.words = 'HR = RR · MAY BE COUNTING THE HEART'; return; }
    if (t.src === 'SOURCE NOT STATED') { t.mark = 'questionable'; t.words = 'SOURCE NOT STATED'; return; }
    t.mark = 'live';
  }

  temp(p, t, V, stale) {
    const unit = String(p.unit ?? '').toUpperCase().replace('°', '');
    t.unit = unit === 'C' || unit === 'F' ? `°${unit}` : '';
    t.src = p.site ? String(p.site).toUpperCase() : 'SITE NOT STATED';
    if (!fin(p.value)) { t.words = 'NO VALUE REPORTED'; return; }
    t.text = val(p.value).toFixed(1);
    if (stale()) return;
    if (!t.unit) { t.mark = 'questionable'; t.words = 'UNIT NOT STATED'; return; }
    if (!p.site) { t.mark = 'questionable'; t.words = 'SITE NOT STATED'; return; }
    t.mark = 'live';
  }

  status(tiles) {
    const on = tiles.filter((t) => t.mark !== 'absent');
    if (!this._v || !on.length) return 'unknown';
    if (on.some((t) => t.alarm || t.mark === 'withheld')) return 'bad';
    if (on.some((t) => t.alarmsOff || !['live', 'taken'].includes(t.mark) || (t.words && t.mark === 'live'))) return 'note';
    return 'ok';
  }

  /* ---- the trend ------------------------------------------------------------ */

  trend(t, now) {
    const W = this.attrNum(this.getAttribute('trend-window'), 1800) * 1000;
    const pts = (this._hist[t.key] || []).filter((e) => e.t <= now && now - e.t <= W);
    const X = (tm) => 120 * (1 - (now - tm) / W);
    const vals = t.key === 'nibp' ? pts.flatMap((e) => [e.sys, e.dia]) : pts.map((e) => e.v).filter((v) => v !== null);
    if (t.limits) vals.push(...t.limits);
    let s = '';
    if (vals.length) {
      let lo = Math.min(...vals);
      let hi = Math.max(...vals);
      if (hi - lo < 1e-9) { lo -= 1; hi += 1; }
      const pad = (hi - lo) * 0.12;
      lo -= pad; hi += pad;
      const Y = (v) => 34 - ((v - lo) / (hi - lo)) * 32;
      if (t.limits) s += `<rect class="ov-vitals__band" x="0" width="120" y="${f1(Y(t.limits[1]))}" height="${f1(Y(t.limits[0]) - Y(t.limits[1]))}"/>`;
      if (t.key === 'nibp') {
        // Refusal: one bar per cuff reading, never joined.
        s += pts.map((e) => `<path class="ov-vitals__bar" d="M${f1(X(e.t))} ${f1(Y(e.sys))}V${f1(Y(e.dia))}${e.mean !== null ? `M${f1(X(e.t) - 2.5)} ${f1(Y(e.mean))}h5` : ''}"/>`).join('');
      } else {
        // The longest step that still counts as the same run: the stale limit,
        // or two and a half times the series' own usual spacing if that is
        // longer, so history handed in once a minute is not all dots.
        const steps = pts.slice(1).map((e, i) => e.t - pts[i].t).sort((a, b) => a - b);
        const usual = steps.length ? steps[steps.length >> 1] : 0;
        const gapMs = Math.max(t.staleMs, usual * 2.5);
        let d = '';
        let prev = null;
        for (const e of pts) {
          if (e.v === null) { prev = null; continue; }
          // Joined only to a neighbour inside that limit, from the same source.
          const join = prev && e.t - prev.t <= gapMs && e.s === prev.s;
          d += join ? `L${f1(X(e.t))} ${f1(Y(e.v))}` : `M${f1(X(e.t))} ${f1(Y(e.v))}h.1`;
          prev = e;
        }
        s += `<path class="ov-vitals__line" d="${d}"/>`;
      }
    }
    s += '<path class="ov-vitals__now" d="M119.5 0V36"/>';
    return `<svg class="ov-vitals__trend" viewBox="0 0 120 36" preserveAspectRatio="none" aria-hidden="true">${s}</svg>`;
  }

  /* ---- drawing ------------------------------------------------------------ */

  unschedule() {
    clearTimeout(this._timer);
    if (this._unarrive) this._unarrive();
    this._unarrive = null;
  }

  schedule(next) {
    this.unschedule();
    if (next === null) return;
    // After arrival whenArrived() runs at once and returns a no-op; keep the
    // unhook only while the page is still arriving.
    let started = false;
    const off = whenArrived(() => {
      started = true;
      this._timer = setTimeout(() => this.paint(), Math.max(0, next - OvVitals.now()) + 20);
    });
    if (!started) this._unarrive = off;
  }

  paint() {
    const now = OvVitals.now();
    const V = this._v;
    const tiles = this.params().map((k) => this.judge(k, V || {}, now));
    const status = this.status(tiles);
    this._report = { status, tiles };
    const win = this.attrNum(this.getAttribute('trend-window'), 1800);

    const row = (t) => `<div class="ov-vitals__row" data-ov-param="${t.key}" data-ov-mark="${t.mark}"${t.alarm ? ' data-ov-alarm' : ''}${t.alarmsOff ? ' data-ov-alarms-off' : ''}>`
      + `<div class="ov-vitals__id"><span class="ov-vitals__label">${esc(t.label)}</span><span class="ov-vitals__src">${esc(t.src)}</span></div>`
      + this.trend(t, now)
      + `<div class="ov-vitals__read"><b class="ov-vitals__num">${esc(t.text)}</b>`
      + `${t.mark === 'questionable' ? '<span class="ov-vitals__q">?</span>' : ''}`
      + `${t.text && t.text !== '-?-' && t.unit ? `<span class="ov-vitals__unit">${esc(t.unit)}</span>` : ''}`
      + `${t.alarmsOff ? '<span class="ov-vitals__off"><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M8 2a4 4 0 0 0-4 4v3L2.5 11.5h11L12 9V6a4 4 0 0 0-4-4zM6.5 13a1.5 1.5 0 0 0 3 0z"/><path class="ov-vitals__slash" d="M2 2l12 12"/></svg>OFF</span>' : ''}</div>`
      + `<div class="ov-vitals__foot"><span class="ov-vitals__words">${t.alarm ? `ALARM: OUTSIDE ${t.limits[0]} TO ${t.limits[1]}${t.words ? ' · ' : ''}` : ''}${esc(t.words)}</span>`
      + `<span class="ov-aside ov-vitals__limits">${t.mark === 'absent' ? '' : t.limits ? `LIMITS ${t.limits[0]} / ${t.limits[1]}` : 'NO LIMITS SET'}</span></div></div>`;

    const html = `<div class="ov-head"><span class="ov-head__name">${esc(this.getAttribute('label') || 'VITALS')}</span></div>`
      + `${this.hasAttribute('demo') ? '<div class="ov-vitals__demo">DEMONSTRATION VALUES · NOT A PATIENT</div>' : ''}`
      + `${V ? '' : '<div class="ov-vitals__void">NOTHING HANDED IN</div>'}`
      + `<div class="ov-vitals__scale">TRENDS: LAST ${ageWords(win)}, AS HANDED IN</div>`
      + `<div class="ov-vitals__rows">${tiles.map(row).join('')}</div>`;
    if (this._html !== html) { this.innerHTML = html; this._html = html; }

    this.setAttribute('role', 'group');
    this.setAttribute('data-ov-status', status);
    if (status === 'bad' || status === 'unknown') this.setAttribute('data-ov-refusal', 'unknown'); else this.removeAttribute('data-ov-refusal');
    this.setAttribute('aria-label', `${this.getAttribute('label') || 'Vitals'}: `
      + tiles.map((t) => `${t.label} ${t.mark === 'absent' ? 'not measured' : t.text && t.text !== '-?-' ? `${t.text}${t.mark === 'questionable' ? ' questionable' : ''}` : 'withheld'}${t.words ? `, ${t.words.toLowerCase()}` : ''}`).join('; '));

    // The status is supplied to the avatar; it decides nothing itself.
    const id = this.getAttribute('avatar');
    const av = id ? document.getElementById(id) : null;
    if (av && av.getAttribute('status') !== status) av.setAttribute('status', status);

    if (status !== this._status) {
      const previous = this._status ?? null;
      this._status = status;
      this.dispatchEvent(new CustomEvent('ov:vitals', { bubbles: true, detail: { status, previous } }));
    }
    const nexts = tiles.map((t) => t.next).filter((n) => n !== null && n > now);
    this.schedule(nexts.length ? Math.min(...nexts) : null);
  }

  get report() { return this._report || null; }
}

define('ov-vitals', OvVitals);
